input.command:
node <<'EOF'
const fs = require('fs'), path = require('path');
const files = [];
const walk = d => { for (const e of fs.readdirSync(d, { withFileTypes: true })) {
  const p = path.join(d, e.name);
  if (e.isDirectory()) walk(p); else if (p.endsWith('.js')) files.push(p); } };
walk('src'); walk('test');
let renames = 0, attempts = 0, changed = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const r = src.match(/\bretryPolicy\b/g)?.length ?? 0;
  const a = src.match(/maxAttempts: 3\b/g)?.length ?? 0;
  if (!r && !a) continue;
  const out = src.replace(/\bretryPolicy\b/g, 'backoffPolicy').replace(/maxAttempts: 3\b/g, 'maxAttempts: 5');
  fs.writeFileSync(f, out);
  renames += r; attempts += a; changed++;
}
console.log(`files changed: ${changed}, retryPolicy renamed: ${renames}, maxAttempts 3->5: ${attempts}`);
EOF
echo "--- remaining:"; grep -rn "retryPolicy\|maxAttempts: 3" src test; echo "(end)"

